#!/usr/bin/env node
// pnpm docs:gen (03 M12.1): regenerate the agent docs that are derived from the command specs.
//
//   node scripts/docs/gen.ts           # write every generated file
//   node scripts/docs/gen.ts --check   # exit 1 and list the stale files, write nothing
//
// The specs are the source of truth (01 §7): the reference is built from `ghx <cmd> --help`, which is
// derived from the same zod schemas `--schema` prints. claude-md-snippet.md and hooks.md are written
// by hand; the skill embeds the snippet. The hook's replaces table is generated here too.
// test/docs.test.ts fails when anything here is stale.
import { readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { commandHelp } from '../../src/cli/help.ts';
import { fsRegistry } from '../../src/cli/registry.ts';
import { type AnyCommandSpec, commandName } from '../../src/core/command.ts';
import { ALLOWED_NAMES } from '../../src/passthrough/policy.ts';

export const ROOT = join(import.meta.dirname, '..', '..');
const SNIPPET = 'docs/agents/claude-md-snippet.md';

const HEADER = '<!-- Generated by `pnpm docs:gen` from the command specs. Do not edit by hand. -->';

interface Help {
  name: string;
  summary: string;
  description: string | null;
  kind: string;
  mode: string;
  positionals: { name: string; required: boolean; variadic: boolean }[];
  flags: {
    flag: string;
    type: string;
    required: boolean;
    enum?: string[];
    default?: unknown;
    multiple?: boolean;
    description: string | null;
  }[];
  jsonOnlyFields: string[];
  input: string;
  examples: { argv: string; note?: string }[];
  replaces: string[];
  timeout: { defaultMs: number; maxMs: number } | null;
}

export async function loadSpecs(): Promise<AnyCommandSpec[]> {
  return fsRegistry([join(ROOT, 'src', 'commands')]).list();
}

function usage(h: Help): string {
  const pos = h.positionals.map((p) => {
    const n = `<${p.name}${p.variadic ? '…' : ''}>`;
    return p.required ? n : `[${n}]`;
  });
  return ['ghx', h.name, ...pos, ...(h.flags.length > 0 ? ['[flags]'] : [])].join(' ');
}

function seconds(ms: number): string {
  return ms % 60_000 === 0 ? `${ms / 60_000}m` : `${ms / 1000}s`;
}

function flagLine(f: Help['flags'][number]): string {
  const value = f.type === 'boolean' ? '' : f.enum ? ` <${f.enum.join('|')}>` : ` <${f.type}>`;
  const notes = [
    f.required ? 'required' : undefined,
    f.multiple ? 'repeatable' : undefined,
    f.default !== undefined ? `default \`${JSON.stringify(f.default)}\`` : undefined,
  ].filter((n) => n !== undefined);
  const tail = notes.length > 0 ? ` (${notes.join(', ')})` : '';
  return `- \`${f.flag}${value}\`${tail}: ${f.description ?? ''}`.trimEnd();
}

function commandSection(spec: AnyCommandSpec): string {
  const h = commandHelp(spec) as unknown as Help;
  const lines = [`## ghx ${h.name}`, '', h.summary, ''];
  const timeout =
    h.timeout === null ? 'no deadline' : `timeout ${seconds(h.timeout.defaultMs)} (max ${seconds(h.timeout.maxMs)})`;
  lines.push(
    `\`${usage(h)}\``,
    '',
    `${h.kind}, ${h.mode === 'stream' ? 'stream' : 'single document'}, ${timeout}.`,
    '',
  );
  if (h.description) lines.push(h.description, '');
  if (h.flags.length > 0) lines.push('Flags:', '', ...h.flags.map(flagLine), '');
  if (h.jsonOnlyFields.length > 0) {
    lines.push(`JSON-only fields: ${h.jsonOnlyFields.map((f) => `\`${f}\``).join(', ')}.`, '');
  }
  lines.push(`Input: ${h.input}`, '');
  if (h.replaces.length > 0) lines.push(`Replaces: ${h.replaces.map((r) => `\`${r}\``).join(', ')}.`, '');
  lines.push('Examples:', '');
  for (const e of h.examples) lines.push(`- \`${e.argv}\`${e.note ? `: ${e.note}` : ''}`);
  lines.push('', `Schema: \`ghx ${h.name} --schema\`.`, '');
  return lines.join('\n');
}

function reference(specs: readonly AnyCommandSpec[]): string {
  const index = specs.map((s) => `- [\`ghx ${commandName(s)}\`](#ghx-${s.name.join('-')}) (${s.kind}): ${s.summary}`);
  return [
    HEADER,
    '',
    '# ghx command reference',
    '',
    'Every command prints one JSON document (or a spill result). Errors are `{"error":{"code","message","hint","details"}}` with a non-zero exit. `ghx <cmd> --help` and `ghx <cmd> --schema` print the same information as JSON.',
    '',
    ...index,
    '',
    '## Passthrough reads',
    '',
    `These gh reads run through ghx in a bounded JSON envelope (\`{passthrough:{argv, exitCode, json|text|stdoutPath, stdoutBytes, stderr}}\`): ${ALLOWED_NAMES.map((n) => `\`ghx ${n}\``).join(', ')}. \`api\` is GET only; \`run view\` without \`--log\`; \`run download\` needs \`-D <dir>\`. Commands ghx wraps (\`gh pr view\`, \`gh pr checks\`, \`gh run view --log\`, \`gh pr merge\`, …) are refused with the exact replacement; other writes are refused.`,
    '',
    ...specs.map(commandSection),
  ].join('\n');
}

function skill(specs: readonly AnyCommandSpec[], snippet: string): string {
  return [
    '---',
    'name: ghx',
    'description: Use for any GitHub PR or CI task (status, why CI failed, waiting for CI, creating, editing, commenting, reviewing, merging). Use ghx instead of raw gh.',
    '---',
    '',
    HEADER,
    '',
    snippet.trimEnd(),
    '',
    '### Commands',
    '',
    ...specs.map((s) => `- \`ghx ${commandName(s)}\` (${s.kind}): ${s.summary}`),
    '',
    'Full reference: `ghx <cmd> --help`, or docs/agents/commands.md in the ghx repo.',
    '',
  ].join('\n');
}

/** Every spec's `replaces`, for the PreToolUse hook (src/hook/rules.ts), which can't load every spec in its latency budget. */
function replacesTable(specs: readonly AnyCommandSpec[]): string {
  const rows = specs
    .flatMap((s) => (s.replaces ?? []).map((pattern) => ({ pattern, command: commandName(s) })))
    .sort((a, b) => a.command.localeCompare(b.command) || a.pattern.localeCompare(b.pattern));
  return `${JSON.stringify(rows, null, 2)}\n`;
}

/** Every generated file, by repo-relative path. */
export async function generate(): Promise<Map<string, string>> {
  const specs = await loadSpecs();
  const snippet = readFileSync(join(ROOT, SNIPPET), 'utf8');
  return new Map([
    ['docs/agents/commands.md', reference(specs)],
    ['docs/agents/skill/ghx/SKILL.md', skill(specs, snippet)],
    ['src/hook/replaces.generated.json', replacesTable(specs)],
  ]);
}

/** Paths whose content on disk differs from what generate() produces. */
export async function stale(): Promise<string[]> {
  const out: string[] = [];
  for (const [path, content] of await generate()) {
    let current: string | undefined;
    try {
      current = readFileSync(join(ROOT, path), 'utf8');
    } catch {
      current = undefined;
    }
    if (current !== content) out.push(path);
  }
  return out;
}

async function main(): Promise<void> {
  if (process.argv.includes('--check')) {
    const s = await stale();
    if (s.length > 0) {
      process.stdout.write(`Stale generated docs (run pnpm docs:gen): ${s.join(', ')}\n`);
      process.exitCode = 1;
    }
    return;
  }
  for (const [path, content] of await generate()) writeFileSync(join(ROOT, path), content);
}

if (import.meta.main) await main();
